// Converts one of fldigi's Feld-Hell raster fonts (src/feld/Feld*.cxx) into
// src/audio/hell-font.js. See third_party/feldhell/README.md.
//
//   node third_party/feldhell/make-font.js /path/to/fldigi/src/feld/FeldHell-12.cxx
'use strict';

const fs = require('node:fs');
const path = require('node:path');

const src = process.argv[2];
if (!src) {
  console.error('usage: node third_party/feldhell/make-font.js /path/to/FeldHell-12.cxx');
  process.exit(2);
}
const text = fs.readFileSync(src, 'utf8');
const glyphs = [];
const re = /\{\s*('(?:\\.|[^'])'|\d+)\s*,\s*\{([^}]*)\}\s*,?\s*\}/g;
let m;
while ((m = re.exec(text))) {
  const ch = m[1].startsWith("'") ? m[1].slice(1, -1).replace(/^\\/, '').charCodeAt(0) : Number(m[1]);
  const rows = m[2].split(',').map((s) => parseInt(s.trim(), 16));
  if (rows.length !== 14 || rows.some((v) => !Number.isFinite(v))) throw new Error(`bad glyph for code ${ch}`);
  glyphs.push({ ch, rows });
}
// fldigi indexes the table as font[c - ' '], so it must hold ' '..'~' in order.
if (glyphs.length !== 95 || glyphs.some((g, i) => g.ch !== 32 + i)) throw new Error('font must list characters 32..126 in order');
const name = path.basename(src);
const hex = (v) => '0x' + v.toString(16).toUpperCase().padStart(4, '0');
const lines = glyphs.map((g) => `  [${g.rows.map(hex).join(', ')}], // ${JSON.stringify(String.fromCharCode(g.ch))}`);
const out = `'use strict';

// Generated by third_party/feldhell/make-font.js from fldigi's ${name}
// (GPL-3, (c) David Freese W1HKJ and the fldigi contributors); do not edit.
//
// One entry per character from ' ' (32) to '~' (126). Each entry is 14 rows,
// top to bottom; in each row bit 15 (0x8000) is the leftmost column. This is
// fldigi's default transmit font ("hell 12", progdefaults.feldfontnbr = 4).

const FONT_NAME = ${JSON.stringify(name.replace(/\.cxx$/, ''))};
const FONT_ROWS = [
${lines.join('\n')}
];

module.exports = { FONT_NAME, FONT_ROWS };
`;
fs.writeFileSync(path.join(__dirname, '..', '..', 'src', 'audio', 'hell-font.js'), out);
console.log(`wrote src/audio/hell-font.js (${glyphs.length} glyphs from ${name})`);
